import sys
import json
from pathlib import Path
from notes import list_notes, add_note

def main():
    if len(sys.argv) < 2:
        print("Usage: python main.py <command> <file> [text]", file=sys.stderr)
        sys.exit(1)

    command = sys.argv[1]
    file_path = sys.argv[2]

    if command == "add":
        if len(sys.argv) < 4:
            print("Error: add command requires a text argument.", file=sys.stderr)
            sys.exit(1)
        text = sys.argv[3]
        try:
            result = add_note(file_path, text)
            print(json.dumps(result))
        except ValueError as e:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)
        except Exception as e:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)

    elif command == "list":
        try:
            notes = list_notes(file_path)
            print(json.dumps(notes))
        except Exception as e:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)

    else:
        print(f"Error: Unknown command '{command}'.", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

